LOCK TABLES `wp_snippets` WRITE;
/*!40000 ALTER TABLE `wp_snippets` DISABLE KEYS */;
INSERT INTO `wp_snippets` VALUES (1,'Make upload filenames lowercase','Makes sure that image and file uploads have lowercase filenames.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.','add_filter( \'sanitize_file_name\', \'mb_strtolower\' );','sample, media','global',0,10,0,'2026-11-04 09:46:54',1,NULL,1,1),(2,'Disable admin bar','Turns off the WordPress admin bar for everyone except administrators.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.','add_action( \'wp\', function () {\n	if ( ! current_user_can( \'manage_options\' ) ) {\n		show_admin_bar( false );\n	}\n} );','sample, admin-bar','front-end',0,10,0,'2026-11-04 09:46:54',1,NULL,1,1),(3,'Allow smilies','Allows smiley conversion in obscure places.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.','add_filter( \'widget_text\', \'convert_smilies\' );\nadd_filter( \'the_title\', \'convert_smilies\' );\nadd_filter( \'wp_title\', \'convert_smilies\' );\nadd_filter( \'get_bloginfo\', \'convert_smilies\' );','sample','global',0,10,0,'2026-11-04 09:46:54',1,NULL,1,1),(4,'Current year','Shortcode for inserting the current year into a post or page..\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.','<?php echo date( \'Y\' ); ?>','sample, dates','content',0,10,0,'2026-11-04 09:46:54',1,NULL,1,1),(5,'اعداد محافظات الشحن','','add_action( \'init\', function () {\n    // تشغيل الإعداد مرة واحدة فقط\n    if ( get_option( \'paris_shipping_zones_imported\' ) ) {\n        return;\n    }\n\n    if ( ! class_exists( \'WC_Shipping_Zone\' ) ) {\n        return;\n    }\n\n    $zones_data = [\n        \'القاهرة الكبرى (القاهرة والجيزة)\' => [\n            \'states\' => [ \'C\', \'GZ\' ],\n            \'cost\'   => 45,\n        ],\n        \'الإسكندرية والبحيرة\' => [\n            \'states\' => [ \'ALX\', \'BH\' ],\n            \'cost\'   => 55,\n        ],\n        \'وجه بحري (الدلتا)\' => [\n            \'states\' => [ \'DK\', \'SHR\', \'GH\', \'KFS\', \'MNF\', \'DT\' ],\n            \'cost\'   => 60,\n        ],\n        \'مدن القناة\' => [\n            \'states\' => [ \'IS\', \'SUZ\', \'PTS\' ],\n            \'cost\'   => 65,\n        ],\n        \'شمال الصعيد (الفيوم، بني سويف، المنيا)\' => [\n            \'states\' => [ \'FYM\', \'BNS\', \'MN\' ],\n            \'cost\'   => 70,\n        ],\n        \'جنوب الصعيد (أسيوط، سوهاج، قنا، الأقصر، أسوان)\' => [\n            \'states\' => [ \'AST\', \'SHG\', \'QN\', \'LX\', \'ASN\' ],\n            \'cost\'   => 80,\n        ],\n        \'المحافظات الحدودية والبحر الأحمر\' => [\n            \'states\' => [ \'MT\', \'RD\', \'WAD\', \'NS\', \'SS\' ],\n            \'cost\'   => 95,\n        ],\n    ];\n\n    foreach ( $zones_data as $zone_name => $data ) {\n        $zone = new WC_Shipping_Zone();\n        $zone->set_zone_name( $zone_name );\n\n        foreach ( $data[\'states\'] as $state_code ) {\n            $zone->add_location( \'EG:\' . $state_code, \'state\' );\n        }\n\n        $zone->save();\n\n        $instance_id = $zone->add_shipping_method( \'flat_rate\' );\n        $option_key  = \'woocommerce_flat_rate_\' . $instance_id . \'_settings\';\n        update_option( $option_key, [\n            \'title\'      => \'شحن إلى \' . $zone_name,\n            \'cost\'       => (string) $data[\'cost\'],\n            \'tax_status\' => \'none\',\n            \'enabled\'    => \'yes\',\n        ] );\n    }\n\n    // علامة لتأكيد عدم تكرار الإعداد\n    update_option( \'paris_shipping_zones_imported\', 1 );\n} );','','global',0,10,1,'2026-11-04 09:48:16',1,NULL,1,1);
/*!40000 ALTER TABLE `wp_snippets` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `wp_srfm_entries`
--

DROP TABLE IF EXISTS `wp_srfm_entries`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wp_srfm_entries` (
  `ID` bigint unsigned NOT NULL AUTO_INCREMENT,
  `form_id` bigint unsigned DEFAULT NULL,
  `user_id` bigint unsigned NOT NULL DEFAULT '0',
  `form_data` longtext COLLATE utf8mb4_unicode_520_ci,
  `logs` longtext COLLATE utf8mb4_unicode_520_ci,
  `notes` longtext COLLATE utf8mb4_unicode_520_ci,
  `submission_info` longtext COLLATE utf8mb4_unicode_520_ci,
  `status` varchar(10) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `type` varchar(20) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `extras` longtext COLLATE utf8mb4_unicode_520_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`ID`),
  KEY `idx_form_id` (`form_id`),
